    Array.isArray(row) &&
    row.length >= 12 &&
    /^\d+$/.test(String(row[0])) &&
    Array.isArray(row[4]) &&
    Array.isArray(row[5]) &&
    Array.isArray(row[6]) &&
    Array.isArray(row[7]) &&
    Array.isArray(row[9]) &&
    Array.isArray(row[10]) &&
    Array.isArray(row[11]) &&
    row[10].length === row[6].length &&
    row[11].length === row[5].length &&
    Number(row[0]) > previousSeq
