function voicePendingNote(id) {
  const pending = el('p', 'play-pending');
  pending.id = id;
  // a status label, like a button's: not prose, so no lookup doors (they were three Tab stops)
  pending.dataset.japaneseLookup = 'off';
  // the two names come from the lock, never from a literal: one value decides what this says
  const mainName = NARRATION_VOICES[VOICE_LOCK.main], secondName = NARRATION_VOICES[VOICE_LOCK.second];
  pending.setAttribute('aria-description', tx(`音声は ${mainName}、第二話者は ${secondName} に固定されています。`,
    `Approved voices: ${mainName} (main), ${secondName} (second).`));
  const sentence = id === 'sentence-listening-pending';
  pending.append(uiIcon('speaker'), el('span', 'l-ja', sentence
    ? tx('この文の収録音声はありません', 'No recording for this sentence')
    : tx('この記事の収録音声はありません', 'No recording for this article')));
  return pending;
}

/** The reader's play bar, built on its own so a late narration manifest can refresh just this
 * row in place — the focused token or glossary entry elsewhere in the reader is never replaced.
 * It carries only the locked narration voice. One glyph when idle (John, 2026-10-15 17:20: "a simple
 * character… elegant and nearly hidden but obvious"): a speaker mark, 44 px, quiet, at the right end of the
 * reader's instrument line (F, the lead's ruling 2026-10-18: never over the reading column); a tap opens the clean
 * bar (play · progress · voice · speed) where it has always stood, a tap on the mark closes it. With no clips for this
 * article in that voice there is no mark at all (no dead control): no picker, no stand-in voice. */
function buildListenRow(p) {
  const listenRow = el('div', 'listen-row play-bar');
  listenRow.dataset.passage = p.id;
  const clips = narrationClips(p);
  const mark = el('button', 'play-mark');
  mark.type = 'button';
  mark.id = 'listen-open';
  mark.append(uiIcon('speaker'));
  if (!clips.length) {
    // F (the lead's ruling, 2026-10-18): with no recording for this article there is no mark at all — no dead control.
    // The row stays as an empty, hidden place (its passage named, so a late manifest can arm it in place)
    listenRow.classList.add('is-pending');
    listenRow.dataset.open = 'false';
    listenRow.hidden = true;
    return listenRow;
  }
  if (readAloud.pid !== p.id) { readAloud.pid = p.id; readAloud.clip = 0; readAloud.failed = null; readAloud.barOpen = false; }
  readAloud.total = clips.length;
  // the bar stands open while it plays, or while the learner holds it open; otherwise it is the mark alone
  const open = readAloud.on || !!readAloud.barOpen;
  listenRow.dataset.open = String(open);
  mark.setAttribute('aria-expanded', String(open));
  mark.setAttribute('aria-label', open ? tx('音声の操作をとじる', 'Close the player') : tx('聞く', 'Listen'));
  mark.addEventListener('click', () => {
    readAloud.barOpen = !open;
    refreshListenRow();
  });
  const listen = el('button', 'play-toggle');
  listen.type = 'button';
  listen.id = 'listen-toggle';
  listen.setAttribute('aria-pressed', String(readAloud.on));
  listen.setAttribute('aria-label', readAloud.on ? tx('止める', 'pause') : tx('聞く', 'listen'));
  listen.append(uiIcon(readAloud.on ? 'pause' : 'play'));
  const track = el('div', 'play-track');
  track.id = 'listen-progress';
  track.setAttribute('role', 'progressbar');
  track.setAttribute('aria-label', tx('再生位置', 'playback position'));
  track.setAttribute('aria-valuemin', '0');
  track.setAttribute('aria-valuemax', '100');
  track.style.setProperty('--played', String(readAloud.clip / clips.length));
  track.setAttribute('aria-valuenow', String(Math.round((readAloud.clip / clips.length) * 100)));
  const failedHere = readAloud.failed?.pid === p.id;
  const listenNote = el('span', 'play-voice', failedHere
    ? tx('再生できませんでした', 'could not play')
    : narrationVoiceName());
  listenNote.id = 'listen-note';
  const rate = el('button', 'play-rate', `${readAloud.rate}×`);
  rate.type = 'button';
  rate.id = 'listen-rate';
  rate.setAttribute('aria-label', tx(`速さ ${readAloud.rate}倍`, `speed ${readAloud.rate}×`));
  rate.addEventListener('click', () => {
    readAloud.rate = LISTEN_RATES[(LISTEN_RATES.indexOf(readAloud.rate) + 1) % LISTEN_RATES.length];
    if (recAudioEl) recAudioEl.playbackRate = readAloud.rate;
    rate.textContent = `${readAloud.rate}×`;
    rate.setAttribute('aria-label', tx(`速さ ${readAloud.rate}倍`, `speed ${readAloud.rate}×`));
  });
  listen.addEventListener('click', () => {
    if (readAloud.on) {
      stopReadAloud();
      refreshListenRow();
      return;
    }
    readAloud.failed = null;
    readAloud.on = true;
    speakPassage(p, () => {
      if (S.view === 'reader') refreshListenRow();
    });
    refreshListenRow();
  });
  listenRow.append(mark, listen, track, listenNote, rate);
  return listenRow;
}
