  svg.setAttribute('viewBox', '0 0 400 80');
  svg.setAttribute('preserveAspectRatio', 'xMidYMax slice');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  const roofs = document.createElementNS(NS, 'path');
