          const score = el('span', 'lesson-score', `${result.score}/${result.total}`);
          if (before) score.append(el('span', 'lesson-score-before', tx(` · 前回 ${before.score}/${before.total}`, ` · last time ${before.score}/${before.total}`)));
          row.append(score);
