    if ((url.protocol === 'https:' || loopback) && !url.search && !url.hash && !url.username && /^[A-Za-z0-9_-]{16,128}$/.test(key))
      return `${url.origin}${url.pathname.replace(/\/+$/, '')}/k/${key}`;
